require '../auth.php';require '../../config/koneksi.php';$id=(int)($_GET['id']??0);$stmt=mysqli_prepare($conn,'SELECT * FROM laporan WHERE id=?');mysqli_stmt_bind_param($stmt,'i',$id);mysqli_stmt_execute($stmt);$data=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));if(!$data){$_SESSION['error']='Laporan tidak ditemukan.';header('Location:index.php');exit;}$allowedTypes=['Keuangan','Kegiatan','Donasi','Pembangunan'];if($_SERVER['REQUEST_METHOD']==='POST'){$judul=trim($_POST['judul']??'');$jenis=$_POST['jenis']??'';$tanggal=$_POST['tanggal']??'';$deskripsi=trim($_POST['deskripsi']??'');if($judul===''||!in_array($jenis,$allowedTypes,true)){$_SESSION['error']='Data laporan tidak valid.';}else{$update=mysqli_prepare($conn,'UPDATE laporan SET judul_laporan=?,jenis_laporan=?,tanggal=?,deskripsi=? WHERE id=?');mysqli_stmt_bind_param($update,'ssssi',$judul,$jenis,$tanggal,$deskripsi,$id);mysqli_stmt_execute($update);$_SESSION['success']='Laporan berhasil diperbarui.';header('Location:index.php');exit;}}
